-- each teacher's summary row (what they mainly teach)
UPDATE teachers t JOIN teaching_assignments a ON a.id = (SELECT MIN(id) FROM teaching_assignments WHERE teacher_id = t.id AND id > @ta0 AND id <= @ta0 + 30)
JOIN sections s ON s.id = a.section_id JOIN strands st ON st.id = s.strand_id
SET t.grade_level = s.grade_level, t.track_id = st.track_id, t.strand_id = s.strand_id, t.section_id = s.id, t.subject_id = a.subject_id, t.updated_at_utc = @now
WHERE t.id > 0 AND t.subject_id IS NULL AND @go = 1;

