INSERT INTO material_questions (item_id, position, text, kind, options_text, correct_answer, points, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @mi0 + 2 AS item_id, 1 AS position, 'Which equation is the basic accounting equation?' AS text, 'MultipleChoice' AS kind, 'Assets = Liabilities + Equity
Assets = Liabilities - Equity
Equity = Assets + Liabilities
