-- ================================================================ 5) Attendance of the last two weeks (school days only)
INSERT INTO attendance_records (assignment_id, student_id, attended_on, status, note, created_at_utc, updated_at_utc)
SELECT a.id, e.student_id, d.day,
  CASE WHEN e.student_id IN (@s_3) THEN CASE WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 45 THEN 'Absent' WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 60 THEN 'Late' ELSE 'Present' END
       ELSE CASE WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 3 THEN 'Absent' WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 9 THEN 'Late' ELSE 'Present' END END,
  NULL, TIMESTAMP(d.day, '17:00:00'), TIMESTAMP(d.day, '17:00:00')
FROM teaching_assignments a
JOIN enrollments e ON e.section_id = a.section_id AND e.id > @e0 AND e.id <= @e0 + 12
JOIN (SELECT DATE_SUB(CURDATE(), INTERVAL n DAY) AS day FROM (SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14) nn) d ON WEEKDAY(d.day) < 5
WHERE a.id > @ta0 AND a.id <= @ta0 + 30 AND @go = 1;

-- ================================================================ 6) Announcements, messages and notifications
INSERT INTO announcements (author_user_id, title, body, audience, category, section_id, assignment_id, expires_on, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @u_coord AS author_user_id, 'Welcome to the new school year' AS title, 'Classes are on. Please check your courses, open your modules and read the syllabus of each one. If something is missing, write to your teacher.' AS body, 'Everyone' AS audience, 'Other' AS category, NULL AS section_id, NULL AS assignment_id, NULL AS expires_on, (@day0 + INTERVAL -35 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -35 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @u_coord, 'Quiz week starts next Monday', 'Quizzes of all courses are open from Monday to Friday. Read the instructions first: some quizzes watch if you leave the page.', 'Students', 'Exam', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 10 DAY), (@day0 + INTERVAL -2 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -2 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_coord, 'Faculty meeting on Friday, 3:00 PM', 'We will talk about the grades of the first term and the teacher evaluation. Please bring the grades of your courses.', 'Teachers', 'TeachersMeeting', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 4 DAY), (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_coord, 'No classes on Monday', 'Monday is a holiday. Classes continue on Tuesday. Enjoy the long weekend and finish your activities before you rest.', 'Everyone', 'Holiday', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 6 DAY), (@day0 + INTERVAL -1 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_coord, 'Semester break', 'The semester break starts after the last exam of the 1st term. The 2nd term starts on Monday, November 2.', 'Everyone', 'SemesterBreak', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 20 DAY), (@day0 + INTERVAL -3 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -3 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
