  UNION ALL SELECT @eq0 + 4, @ev0 + 1, 4, 'How often does the teacher answer questions and give feedback on time?', 'Frequency', NULL, 'Communication', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 5, @ev0 + 1, 5, 'The activities and quizzes match what was taught.', 'Likert', NULL, 'Assessment', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 6, @ev0 + 1, 6, 'Overall, how would you rate this teacher?', 'Performance', NULL, 'Overall', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 7, @ev0 + 1, 7, 'Would you recommend this teacher to other students?', 'Binary', NULL, 'Overall', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 8, @ev0 + 1, 8, 'Rank what helps you learn the most, from the first (best) to the last.', 'Ranking', 'Explanations in class
