  UNION ALL SELECT @eq0 + 11, @ev0 + 1, 11, 'What can your teacher do better?', 'Comment', NULL, 'Comments', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
) AS r WHERE @go = 1;

